    (12, 0, 'Artifacts', null),
    (12, 1, 'Task', 'Apply the day''s technique to something on your own desk.'),
    (12, 4, 'Example 4', null),
    (13, 0, 'Design', null),
    (13, 1, 'Task', 'Apply the day''s technique to something on your own desk.'),
    (13, 2, 'Live session 3', null),
    (13, 4, 'Capstone', null),
    (14, 0, 'Dispatch + Plugins', null),
    (14, 1, 'Task', 'Apply the day''s technique to something on your own desk.'),
